// Get collection IDs from the Route node
const collectionIds = [
  $('🔀 Route: Create or Update').item?.json?.collection_id1,
  $('🔀 Route: Create or Update').item?.json?.collection_id2,
  $('🔀 Route: Create or Update').item?.json?.collection_id3,
  $('🔀 Route: Create or Update').item?.json?.collection_id4,
].filter(id => id !== null && id !== undefined && id !== '');

// Get product ID from current input
const productId = $input.first().json.product.id;

// If no valid collections → do nothing
if (collectionIds.length === 0) {
  return [];
}

// Create one item per valid collection
return collectionIds.map(collection_id => ({
  collect: {
    product_id: productId,
    collection_id: String(collection_id),
  }
}));

// metafieldsSet is a true upsert -- it needs ownerId + namespace + key, not the
// metafield's own id. owner_id/namespace/key were added onto this "update"
// operation object in "🧠 Sync Metafields" (additive fields only, the
// create/update/delete decision logic there is untouched).
const QUERY = `mutation MetafieldsSet($metafields: [MetafieldsSetInput!]!) {
  metafieldsSet(metafields: $metafields) {
    metafields { id }
    userErrors { field message code }
  }
}`;

// Runs once per input item -- multiple metafield updates can be in flight at
// once (the default "run once for all items" Code node mode only sees $json
// as the first item, silently dropping the rest).
return $input.all().map(item => {
  const op = item.json;
  const m = op.payload.metafield;
  return {
    json: {
      body: {
        query: QUERY,
        variables: {
          metafields: [{
            ownerId: `gid://shopify/Product/${op.owner_id}`,
            namespace: op.namespace,
            key: op.key,
            type: m.type,
            value: m.value
          }]
        }
      }
    }
  };
});

// Runs once per input item -- multiple collection-add calls can be in flight
// at once, each with its own response to check. A failure here (e.g. the
// product already existed on Shopify from a race, or a transient Shopify
// error) must not throw and abort the run -- collection assignment is a lesser
// concern than blocking the rest of this product's processing over it.
return $input.all().map(item => {
  const res = item.json;
  const errors = res?.errors;
  const userErrors = res?.data?.collectionAddProducts?.userErrors;
  if (errors?.length || userErrors?.length) {
    return { json: { added: false, error: JSON.stringify(errors?.length ? errors : userErrors) } };
  }
  return { json: { added: true } };
});

// REST auto-publishes a newly created product to the Online Store sales
// channel; GraphQL's productSet/productCreate does not -- status: ACTIVE only
// means "publishable", not published to any channel. This looks up the
// store's "Online Store" publication and explicitly publishes the product to
// it, so newly created products actually appear on the live storefront.
const res = $json;
if (res?.errors?.length) {
  throw new Error('Shopify GraphQL error (get publications): ' + JSON.stringify(res.errors));
}
const pubs = res?.data?.publications?.nodes || [];
const onlineStore = pubs.find(p => p.name === 'Online Store');
if (!onlineStore) {
  throw new Error('Could not find an "Online Store" publication/sales channel on this shop: ' + JSON.stringify(pubs));
}

const product = $('🔀 Adapt Response: Create Product').item.json.product;

const QUERY = `mutation PublishProduct($id: ID!, $input: [PublicationInput!]!) {
  publishablePublish(id: $id, input: $input) {
    publishable {
      ... on Product { id }
    }
    userErrors { field message }
  }
}`;

return [{
  json: {
    body: {
      query: QUERY,
      variables: {
        id: `gid://shopify/Product/${product.id}`,
        input: [{ publicationId: onlineStore.id }]
      }
    }
  }
}];

const base    = $('🚀 Triggered by Main Pipeline (per product)').first().json;
const checks  = $('🩺 Build Image Checks').all();
const results = $input.all();

// Only a definitive "gone" counts as dead; timeouts / 5xx / 429 are transient and
// must not treat a real, live photo as missing over a flaky moment.
//
// A confirmed-dead source is treated exactly like an empty IMAGE URL cell --
// excluded from what gets built/pushed for this product, never blocking the
// rest of the update. Downstream, "🔀 Build GraphQL: Sync Product Images"'s
// existing "slot missing from desired = delete" rule then removes that slot's
// stale Shopify media too, the same as it already does for a genuinely empty
// cell -- there is no separate "skip this whole product" path anymore.
const DEAD = new Set([404, 410]);
const dead = [];
const deadIdx = new Set();
for (let i = 0; i < results.length; i++) {
  const c = checks[i]?.json;
  const status = results[i]?.json?.statusCode;
  if (!c || !DEAD.has(status)) continue;
  dead.push({ slot: c.idx + 1, alt: c.alt, src: c.url, status });
  deadIdx.add(c.idx);
}

const filteredImages = (base.product?.images || []).filter((img, idx) => !deadIdx.has(idx));
const product = base.product ? { ...base.product, images: filteredImages } : base.product;

return [{
  json: { ...base, product, dead_images: dead },
  pairedItem: { item: 0 }
}];

const res = $json;
if (res?.errors?.length) {
  throw new Error('Shopify GraphQL error (productVariantsBulkUpdate): ' + JSON.stringify(res.errors));
}
const userErrors = res?.data?.productVariantsBulkUpdate?.userErrors;
if (userErrors?.length) {
  throw new Error('Shopify productVariantsBulkUpdate userErrors: ' + JSON.stringify(userErrors));
}
return [{ json: {} }];

// Runs once per input item -- multiple metafield deletes can be in flight at once.
return $input.all().map(item => {
  const res = item.json;
  if (res?.errors?.length) {
    throw new Error('Shopify GraphQL error (metafieldsDelete): ' + JSON.stringify(res.errors));
  }
  const userErrors = res?.data?.metafieldsDelete?.userErrors;
  if (userErrors?.length) {
    throw new Error('Shopify metafieldsDelete userErrors: ' + JSON.stringify(userErrors));
  }
  return { json: {} };
});

// Reshapes into the REST-shaped { collects: [{id, collection_id}] } array that
// "❓ Has Existing Collections?" and "🔧 Extract Collects to update or delete"
// already expect unchanged. GraphQL has no separate "collect join-record id"
// concept -- a collection's own id doubles as the collect_id here, which is
// exactly what the new collection-removal call needs anyway.
const res = $json;
if (res?.errors?.length) {
  throw new Error('Shopify GraphQL error (get collections): ' + JSON.stringify(res.errors));
}
const productId = $('📝 Format Update Request').item.json.product.id;
const edges = res?.data?.product?.collections?.edges || [];
const collects = edges.map(e => ({
  id: e.node.legacyResourceId,
  collection_id: e.node.legacyResourceId,
  product_id: productId
}));
return [{ json: { collects } }];

// ============================================
// CONFIGURATION
// ============================================
const CONFIG = {
  METADATA_FIELDS: new Set([
    'l_cm','w_cm','h_cm','d_cm','t_cm',
    'l_in','w_in','h_in','d_in','t_in',
    'opening_w_cm', 'opening_h_cm', 'opening_w_in', 'opening_h_in',
    'material','description',
    'weight','product_number',
    'sheet_name','row_number',
    'drain_diameter','radius',
    'surface','signature',
    'material_catalog_url',
    'care_guide_url',
    'cad_drawing_url',
    'price_unit_suffix',
    'seo_title',
    'seo_description'
  ])
};

// ============================================
// HELPERS
// ============================================
const hasValue = (v) =>
  v !== null &&
  v !== undefined &&
  v !== '' &&
  v !== 0 &&
  v !== '0';

// ============================================
// SEO NORMALIZER (IMPORTANT FIX)
// ============================================
const getSeoTitle = (p) => {
  return (
    p?.seo_title ||
    ''
  );
};

const getSeoDescription = (p) => {
  return (
    p?.seo_description ||
    p?.description ||
    ''
  );
};

// ============================================
// BUILD METAFIELDS
// ============================================
const buildMetafields = (p) => {
  const metafields = [];

  // -------------------------
  // Custom URLs
  // -------------------------
  if (hasValue(p.material_catalog_url)) {
    metafields.push({
      namespace: "custom",
      key: "material_catalog_url",
      type: "url",
      value: p.material_catalog_url
    });
  }

  if (hasValue(p.care_guide_url)) {
    metafields.push({
      namespace: "custom",
      key: "care_guide_url",
      type: "url",
      value: p.care_guide_url
    });
  }

  if (hasValue(p.cad_drawing_url)) {
    metafields.push({
      namespace: "custom",
      key: "cad_drawing_url",
      type: "url",
      value: p.cad_drawing_url
    });
  }

  // -------------------------
  // Price display suffix (e.g. "/piece")
  // -------------------------
  if (hasValue(p.price_unit_suffix)) {
    metafields.push({
      namespace: "custom",
      key: "price_unit_suffix",
      type: "single_line_text_field",
      value: p.price_unit_suffix
    });
  }

  // -------------------------
  // SEO FIELDS (ROBUST FIX)
  // -------------------------
  const seoTitle = getSeoTitle(p);
  const seoDescription = getSeoDescription(p);

  if (hasValue(seoTitle)) {
    metafields.push({
      namespace: "global",
      key: "title_tag",
      type: "single_line_text_field",
      value: String(seoTitle).slice(0, 70)
    });
  }

  if (hasValue(seoDescription)) {
    metafields.push({
      namespace: "global",
      key: "description_tag",
      type: "multi_line_text_field",
      value: String(seoDescription).slice(0, 320)
    });
  }

  return metafields;
};

// ============================================
// BODY HTML BUILDER
// ============================================
const field = (label, value, suffix = '') =>
  hasValue(value)
    ? `<p><strong>${label}:</strong> ${value}${suffix}</p>`
    : '';

const buildDimLine = (items, unit) => {
  const line = items
    .filter(([, v]) => hasValue(v))
    .map(([label, v]) => `<strong>${label}:</strong> ${v} ${unit}`)
    .join('&nbsp;&nbsp;');

  return hasValue(line) ? `<p>${line}</p>` : '';
};

const buildBodyHtml = (p) => {
  const sections = [];

  const isFireplace = p.sheet_name === 'Fireplace'  || p.sheet_name === 'Test data';
  const isCarving = p.sheet_name === 'Carving';
  const isWindowSurround = p.sheet_name === 'WindowSurround';
  const isWallCoverings = p.sheet_name === 'Wall-Coverings';
  const isExteriorWallDecoration = p.sheet_name === 'Exterior-Wall-Decoration';
  const isMarbleSlab = p.sheet_name === 'MarbleSlab';
  const isMarbleRangeHood =
    p.sheet_name === 'MarbleRangeHood';
  const isMoulding =
    p.sheet_name === 'Moulding';
  const isStoneMosaicTile =
    p.sheet_name === 'StoneMosaicTile';
  const isMarbleMedallion =
    p.sheet_name === 'MarbleMedallion';
  const isWainscoting =
    p.sheet_name === 'Wainscoting';

  const isOutdoorCornice =
    p.sheet_name === 'OutdoorCornice';

  const isBookMatchedSlabs =
    p.sheet_name === 'BookMatchedSlabs';

  const isStairs =
    p.sheet_name === 'Stairs';

  const isBalustrade =
    p.sheet_name === 'Balustrade';

  const dimensionConfig = isMarbleSlab || isWallCoverings || isStoneMosaicTile || isMarbleMedallion || isExteriorWallDecoration || isWainscoting
    ? [
        { label: 'Length', cm: p.l_cm, inch: p.l_in },
        { label: 'Width', cm: p.w_cm, inch: p.w_in },
        { label: 'Thickness', cm: p.t_cm, inch: p.t_in }
      ]
    : isFireplace || isMarbleRangeHood || isCarving || isWindowSurround
    ? [
        { label: 'Width', cm: p.w_cm, inch: p.w_in },
        { label: 'Height', cm: p.h_cm, inch: p.h_in },
        { label: 'Depth', cm: p.d_cm, inch: p.d_in },
      ]
    : isMoulding
    ? [
        { label: 'Length', cm: p.l_cm, inch: p.l_in },
        { label: 'Height', cm: p.h_cm, inch: p.h_in },
        { label: 'Thickness', cm: p.t_cm, inch: p.t_in }
      ]
    : isOutdoorCornice
    ? [
        { label: 'Length', cm: p.l_cm, inch: p.l_in },
        { label: 'Height', cm: p.h_cm, inch: p.h_in },
        { label: 'Projection', cm: p.p_cm, inch: p.p_in }
      ]
    : isStairs
    ? [
        { label: 'Width', cm: p.w_cm, inch: p.w_in },
        { label: 'Height', cm: p.h_cm, inch: p.h_in },
        { label: 'Diameter', cm: p.diam_cm, inch: p.diam_in },
      { label: 'Inner Opening Diameter', cm: p.io_diam_cm, inch: p.io_diam_in },
      ]
    : isBalustrade
    ? [
        { label: 'Overall Height', cm: p.oh_cm, inch: p.oh_in },
        { label: 'Handrail Height', cm: p.hh_cm, inch: p.hh_in },
        { label: 'Handrail Width', cm: p.hw_cm, inch: p.hw_in },
        { label: 'Baluster Diameter', cm: p.bd_cm, inch: p.bd_in },
        { label: 'Baluster Height', cm: p.bh_cm, inch: p.bh_in },
        { label: 'Base/Plinth Width', cm: p.bpw_cm, inch: p.bpw_in },
        { label: 'Base/Plinth Height', cm: p.bph_cm, inch: p.bph_in },
      ]
    : isBookMatchedSlabs
    ? [
        { label: 'Length', cm: p.l_cm, inch: p.l_in },
        { label: 'Width', cm: p.w_cm, inch: p.w_in },
      ]
    : [
        { label: 'Length', cm: p.l_cm, inch: p.l_in },
        { label: 'Width', cm: p.w_cm, inch: p.w_in },
        { label: 'Height', cm: p.h_cm, inch: p.h_in }
      ];

  const cmDims = buildDimLine(
    dimensionConfig.map(d => [d.label, d.cm]),
    'cm'
  );

  const inDims = buildDimLine(
    dimensionConfig.map(d => [d.label, d.inch]),
    'In'
  );

  if (cmDims || inDims) {
    sections.push('<p><strong>Dimensions</strong></p>');
    if (cmDims) sections.push(cmDims);
    if (inDims) sections.push(inDims);
  }

  const openingSizeConfig = isFireplace
    ? [
        { label: 'Width', cm: p.opening_w_cm, inch: p.opening_w_in },
        { label: 'Height', cm: p.opening_h_cm, inch: p.opening_h_in },
      ]
    : [];

  const cmOpeningSize = buildDimLine(
    openingSizeConfig.map(o => [o.label, o.cm]),
    'cm'
  );

  const inOpeningSize = buildDimLine(
    openingSizeConfig.map(o => [o.label, o.inch]),
    'In'
  );

  if (cmOpeningSize || inOpeningSize) {
    sections.push('<p><strong>Opening Size</strong></p>');
    if (cmOpeningSize) sections.push(cmOpeningSize);
    if (inOpeningSize) sections.push(inOpeningSize);
  }

  if (hasValue(p.material)) sections.push(field('Material', p.material));
  if (hasValue(p.weight)) sections.push(field('Weight', p.weight, ' kg'));
  if (hasValue(p.description)) sections.push(`<p>${p.description}</p>`);
  if (hasValue(p.drain_diameter)) sections.push(field('Drain Diameter', p.drain_diameter));
  if (hasValue(p.radius)) sections.push(field('Radius', p.radius));
  if (hasValue(p.surface)) sections.push(field('Surface', p.surface));
  if (hasValue(p.signature)) sections.push(p.signature);
  if (hasValue(p.product_number)) sections.push(field('Product Number', p.product_number));

  return sections.join('');
};

// ============================================
// MAIN
// ============================================
const product = items?.[0]?.json?.product;
if (!product) return [];

const bodyHtml = buildBodyHtml(product);
const metafields = buildMetafields(product);

// Safe handle fallback
const handleFallback =
  product.handle ||
  `${product.title || 'product'}-${product.material || ''}-${product.product_number || ''}`
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

const cleanedProduct = Object.fromEntries(
  Object.entries({
    ...product,

    handle: handleFallback,

    ...(hasValue(bodyHtml) ? { body_html: bodyHtml } : {}),
    ...(metafields.length > 0 ? { metafields } : {})
  }).filter(([key]) => !CONFIG.METADATA_FIELDS.has(key))
);

return [
  {
    json: {
      product: cleanedProduct
    }
  }
];

// Reshapes into the SAME { product: { id, title, handle, variants: [{id}] } }
// shape "Adapt Response: Create Product" produces on a normal success, so
// everything downstream (publish, collection mapping, sheet write-back) works
// identically whether the product was just created or recovered here.
const res = $json;
if (res?.errors?.length) {
  throw new Error('Shopify GraphQL error (find product by handle): ' + JSON.stringify(res.errors));
}
const product = res?.data?.productByHandle;
if (!product) {
  // Shopify said the handle was taken, but a direct lookup by that same
  // handle found nothing -- a genuinely confusing state worth surfacing
  // loudly rather than silently creating a duplicate or looping forever.
  const attemptedHandle = $('🔍 Build GraphQL: Find Product By Handle').item.json.body.variables.handle;
  throw new Error(`Handle "${attemptedHandle}" was reported as already in use, but no product with that handle could be found.`);
}

const variantEdge = product.variants?.edges?.[0]?.node;

return [{
  json: {
    product: {
      id: product.legacyResourceId,
      title: product.title,
      handle: product.handle,
      variants: [{ id: variantEdge?.legacyResourceId ?? '' }]
    }
  }
}];

// Runs once per input item -- the sync builds several operations per product
// (attach / update / create / detach / delete / reorder), each answered by one
// response, in the same order.
const FILE_UPDATE_TYPES = new Set(['update', 'attach', 'detach']);
const errorsFor = (type, res) => {
  if (FILE_UPDATE_TYPES.has(type)) return res?.data?.fileUpdate?.userErrors;
  if (type === 'delete') return res?.data?.fileDelete?.userErrors;
  if (type === 'reorder') return res?.data?.productReorderMedia?.mediaUserErrors;
  return res?.data?.productCreateMedia?.mediaUserErrors;
};

return $input.all().map((item, i) => {
  const res = item.json;
  const type = $('🔀 Build GraphQL: Sync Product Images').all()[i]?.json?.type;

  // Re-ordering only affects gallery order, never which photos exist, so a
  // failure there must not fail the whole product's sync.
  if (type === 'reorder') {
    const problems = res?.errors?.length ? res.errors : errorsFor(type, res);
    if (problems?.length) return { json: { skipped: true, reason: 'REORDER_FAILED', problems } };
    return { json: {} };
  }

  if (res?.errors?.length) {
    throw new Error(`Shopify GraphQL error (${type || 'sync images'}): ` + JSON.stringify(res.errors));
  }

  const userErrors = errorsFor(type, res);

  if (userErrors?.length) {
    // Shopify processes a freshly uploaded/created file asynchronously (download,
    // transcode, thumbnail) before it reaches READY state -- fileUpdate rejects
    // any attempt to touch a file that's still processing (NON_READY_STATE).
    // This is transient: the file becomes updatable within moments on Shopify's
    // own side, and the next image-triggered sync pass will pick up the
    // correction then. Halting the ENTIRE product's sync (body_html, metafields,
    // collections all run in parallel branches feeding the same Merge) over a
    // timing race that resolves itself on its own is worse than skipping this
    // one file update for now.
    const onlyTransient = userErrors.every(e => e.code === 'NON_READY_STATE');
    if (onlyTransient) {
      return { json: { skipped: true, reason: 'NON_READY_STATE', userErrors } };
    }
    throw new Error(`Shopify ${type} image userErrors: ` + JSON.stringify(userErrors));
  }

  return { json: {} };
});

// ============================================
// CONFIGURATION
// ============================================
const CONFIG = {
    DIMENSION_FIELDS: new Set([
    'Length CM','Width CM','Height CM','Depth CM', 'Thickness CM', 'Projection CM',
    'Diameter CM', 'Inner Opening Diameter CM',
    'Overall Height CM', 'Handrail Height CM', 'Handrail Width CM', 'Baluster Diameter CM',
    'Baluster Height CM', 'Base/Plinth Width CM', 'Base/Plinth Height CM',
    'Length Inch','Width Inch','Height Inch','Depth Inch', 'Thickness Inch', 'Projection Inch',
    'Diameter Inch', 'Inner Opening Diameter Inch',
    'Overall Height Inch', 'Handrail Height Inch', 'Handrail Width Inch', 'Baluster Diameter Inch',
    'Baluster Height Inch', 'Base/Plinth Width Inch', 'Base/Plinth Height Inch'
  ]),

  OPENING_SIZE_FIELDS: new Set([
    'Width_CM', 'Height_CM', 'Width_Inch', 'Height_Inch',
  ]),
  CONTENT_FIELDS: new Set([
    'Material','Description_Shopify','Weight KG','Product No.',
    'Surface','Drain_Diameter','Radius','Signature'
  ]),
  TITLE_FIELD: 'Title_Shopify',
  TAGS_SHOPIFY: 'Tags_Shopify',
  COLLECTION_ID1: 'Collection_ID1',
  COLLECTION_ID2: 'Collection_ID2',
  COLLECTION_ID3: 'Collection_ID3',
  COLLECTION_ID4: 'Collection_ID4',
  PRICE_FIELD: 'Price IN USD $ (Jack)',
  WEIGHT_FIELD: 'Weight KG',

  // SEO Fields
  SEO_TITLE_FIELD: 'Shopify_SEO_Title',
  SEO_DESC_FIELD: 'Shopify_SEO_Description',

  // ✅ NEW (metafield trigger fields)
  META_URL_FIELDS: new Set([
    'Material Catalog URL',
    'Care Guide URL',
    'CAD Drawing URL'
  ]),

  PATTERNS: {
    PRODUCT_ID: /\/products\/(\d+)/,
    VARIANT_ID: /[?&]variant=(\d+)/
  }
};

const ALL_BODY_FIELDS = new Set([...CONFIG.DIMENSION_FIELDS,...CONFIG.OPENING_SIZE_FIELDS, ...CONFIG.CONTENT_FIELDS]);

// ============================================
// UTILITIES
// ============================================

const normalizeUrl = (url) => {
  if (!url) return '';
  return String(url).trim().replace(/\+$/, '');
};

const extractId = (url, pattern) => url?.match(pattern)?.[1] ?? '';
const getVariantId = (url) => extractId(url, CONFIG.PATTERNS.VARIANT_ID);
const extractProductId = (url) => extractId(url, CONFIG.PATTERNS.PRODUCT_ID);

const parseUpdateFields = (fieldsStr) =>
  fieldsStr?.split(',').map(f => f.trim()).filter(Boolean) ?? [];

const shouldUpdateBody = (updateList) =>
  updateList.some(field => ALL_BODY_FIELDS.has(field));

const hasValue = (v) => {
  if (Array.isArray(v)) return v.length > 0;
  if (typeof v === 'object' && v !== null) return Object.keys(v).length > 0;
  return v !== undefined && v !== null && v !== '';
};

const field = (label, value, suffix = '') =>
  hasValue(value) ? `<p><strong>${label}:</strong> ${value}${suffix}</p>` : '';

// ============================================
// HTML BUILDER
// ============================================

const buildDimensionLine = (dims) =>
  dims.filter(([, v]) => hasValue(v))
      .map(([label, v, unit]) => `<strong>${label}:</strong> ${v} ${unit}`)
      .join(' &nbsp; ');

const buildBodyHtml = (p) => {
  const isFireplace = p.sheet_name === 'Fireplace' || p.sheet_name === 'Test data';
  const isCarving = p.sheet_name === 'Carving';
  const isWindowSurround = p.sheet_name === 'WindowSurround';
  const isWallCoverings = p.sheet_name === 'Wall-Coverings';
    const isExteriorWallDecoration = p.sheet_name === 'Exterior-Wall-Decoration';
  const isMarbleSlab = p.sheet_name === 'MarbleSlab';
  const isMarbleRangeHood = p.sheet_name === 'MarbleRangeHood';
  const isMoulding = p.sheet_name === 'Moulding';
  const isStoneMosaicTile = p.sheet_name === 'StoneMosaicTile';
  const isMarbleMedallion = p.sheet_name === 'MarbleMedallion';
  const isWainscoting =
    p.sheet_name === 'Wainscoting';
  const isOutdoorCornice =
    p.sheet_name === 'OutdoorCornice';

  const isBookMatchedSlabs =
    p.sheet_name === 'BookMatchedSlabs';

  const isStairs =
    p.sheet_name === 'Stairs';

  const isBalustrade =
    p.sheet_name === 'Balustrade';

  // =========================
  // SINGLE SOURCE DIM CONFIG
  // =========================
  const dimensionConfig = isMarbleSlab || isWallCoverings || isStoneMosaicTile || isMarbleMedallion || isExteriorWallDecoration || isWainscoting
    ? [
        { label: 'Length', cm: p.l_cm, inch: p.l_in },
        { label: 'Width', cm: p.w_cm, inch: p.w_in },
        { label: 'Thickness', cm: p.t_cm, inch: p.t_in }
      ]
    : isFireplace || isMarbleRangeHood || isCarving || isWindowSurround
    ? [
        { label: 'Width', cm: p.w_cm, inch: p.w_in },
        { label: 'Height', cm: p.h_cm, inch: p.h_in },
        { label: 'Depth', cm: p.d_cm, inch: p.d_in },
      ]
    : isMoulding
    ? [
        { label: 'Length', cm: p.l_cm, inch: p.l_in },
        { label: 'Height', cm: p.h_cm, inch: p.h_in },
        { label: 'Thickness', cm: p.t_cm, inch: p.t_in }
      ]
    : isOutdoorCornice
    ? [
        { label: 'Length', cm: p.l_cm, inch: p.l_in },
        { label: 'Height', cm: p.h_cm, inch: p.h_in },
        { label: 'Projection', cm: p.p_cm, inch: p.p_in }
      ]
    : isStairs
    ? [
        { label: 'Width', cm: p.w_cm, inch: p.w_in },
        { label: 'Height', cm: p.h_cm, inch: p.h_in },
        { label: 'Diameter', cm: p.diam_cm, inch: p.diam_in },
      { label: 'Inner Opening Diameter', cm: p.io_diam_cm, inch: p.io_diam_in },
      ]
    : isBalustrade
    ? [
        { label: 'Overall Height', cm: p.oh_cm, inch: p.oh_in },
        { label: 'Handrail Height', cm: p.hh_cm, inch: p.hh_in },
        { label: 'Handrail Width', cm: p.hw_cm, inch: p.hw_in },
        { label: 'Baluster Diameter', cm: p.bd_cm, inch: p.bd_in },
        { label: 'Baluster Height', cm: p.bh_cm, inch: p.bh_in },
        { label: 'Base/Plinth Width', cm: p.bpw_cm, inch: p.bpw_in },
        { label: 'Base/Plinth Height', cm: p.bph_cm, inch: p.bph_in },
      ]
    : isBookMatchedSlabs
    ? [
        { label: 'Length', cm: p.l_cm, inch: p.l_in },
        { label: 'Width', cm: p.w_cm, inch: p.w_in },
      ]
    : [
        { label: 'Length', cm: p.l_cm, inch: p.l_in },
        { label: 'Width', cm: p.w_cm, inch: p.w_in },
        { label: 'Height', cm: p.h_cm, inch: p.h_in }
      ];

  // =========================
  // BUILD LINES
  // =========================
  const cmLine = buildDimensionLine(
    dimensionConfig.map(d => [d.label, d.cm, 'cm'])
  );

  const inLine = buildDimensionLine(
    dimensionConfig.map(d => [d.label, d.inch, 'In'])
  );

  // =========================
  // SINGLE SOURCE Openiing Size CONFIG
  // =========================
  const openingSizeConfig = isFireplace
    ? [
        { label: 'Width', cm: p.opening_w_cm, inch: p.opening_w_in },
        { label: 'Height', cm: p.opening_h_cm, inch: p.opening_h_in },
      ]
    : [];

  // =========================
  // BUILD LINES
  // =========================
  const cmOpeningLine = buildDimensionLine(
    openingSizeConfig.map(o => [o.label, o.cm, 'cm'])
  );

  const inOpeningLine = buildDimensionLine(
    openingSizeConfig.map(o => [o.label, o.inch, 'In'])
  );

  return [
    (cmLine || inLine) && '<p><strong>Dimensions</strong></p>',
    cmLine && `<p>${cmLine}</p>`,
    inLine && `<p>${inLine}</p>`,
    (cmOpeningLine || inOpeningLine) && '<p><strong>Opening Size</strong></p>',
    cmOpeningLine && `<p>${cmOpeningLine}</p>`,
    inOpeningLine && `<p>${inOpeningLine}</p>`,
    field('Material', p.material),
    field('Weight', p.weight, ' kg'),
    hasValue(p.description) && `<p>${p.description}</p>`,
    field('Drain Diameter', p.drain_diameter),
    field('Radius', p.radius),
    field('Surface', p.surface),
    p.signature,
    field('Product Number', p.product_number)
  ].filter(Boolean).join('');
};

// ============================================
// BUILDERS
// ============================================

const buildVariants = (product, updateList) => {
  const variant = {};

  const variantId = getVariantId(product.public_shopify_url);
  if (variantId) variant.id = variantId;

  if (updateList.includes(CONFIG.PRICE_FIELD)) {
    variant.price = product.variants?.[0]?.price;
  }

  if (updateList.includes(CONFIG.WEIGHT_FIELD)) {
    variant.weight = product.weight;
  }

  return Object.keys(variant).length > 0 ? [variant] : [];
};

const hasAnyImageUpdate = (updateList) =>
  updateList.some(f => /^IMAGE URL\d+$/.test(f));

const buildImages = (product, updateList) => {
  if (!hasAnyImageUpdate(updateList)) return [];
  if (!Array.isArray(product.images) || product.images.length === 0) return [];

  return product.images
    .filter(img => img?.src)
    .map(img => ({ src: img.src, alt: img.alt }));
};

// ============================================
// CORE UPDATE PAYLOAD
// ============================================

const buildUpdatePayload = (product, updateList) => {
  const input = $input.first().json;

  const payload = {
    id: extractProductId(product.admin_shopify_url),
  };

  // ======================
  // BODY HTML
  // ======================
  if (shouldUpdateBody(updateList)) {
    const bodyHtml = buildBodyHtml(product);
    if (bodyHtml) payload.body_html = bodyHtml;
  }

  // ======================
  // VARIANTS
  // ======================
  const variants = buildVariants(product, updateList);
  if (variants.length > 0) payload.variants = variants;

  // ======================
  // TITLE
  // ======================
  if (updateList.includes(CONFIG.TITLE_FIELD) && product.title) {
    payload.title = product.title;
  }

  // ======================
  // TAGS
  // ======================
  if (updateList.includes(CONFIG.TAGS_SHOPIFY) && input.product?.tags) {
    payload.tags = input.product.tags;
  }

  // ======================
  // IMAGES
  // ======================
  const images = buildImages(product, updateList);
  if (images.length > 0) payload.images = images;

  // ======================
  // COLLECTIONS
  // ======================
  if (
    updateList.includes(CONFIG.COLLECTION_ID1) ||
    updateList.includes(CONFIG.COLLECTION_ID2) ||
    updateList.includes(CONFIG.COLLECTION_ID3) ||
    updateList.includes(CONFIG.COLLECTION_ID4)
  ) {
    payload.collection_id1 = input.collection_id1 ?? '';
    payload.collection_id2 = input.collection_id2 ?? '';
    payload.collection_id3 = input.collection_id3 ?? '';
    payload.collection_id4 = input.collection_id4 ?? '';
  }

  // ======================
  // ✅ METAFIELD DATA (CRITICAL)
  // ======================
  if (updateList.includes('Material Catalog URL')) {
    payload.material_catalog_url =    normalizeUrl(product.material_catalog_url) ?? '';
   }

  if (updateList.includes('Care Guide URL')) {
     payload.care_guide_url = normalizeUrl(product.care_guide_url)      ?? '';
  }

  if (updateList.includes('CAD Drawing URL')) {
    payload.cad_drawing_url = normalizeUrl(product.cad_drawing_url) ?? '';
  }

  // Always included -- not gated by Fields_to_update, since this is a computed
  // value based on category, not a column Luna edits directly.
  payload.price_unit_suffix = product.price_unit_suffix ?? '';

  // ======================
  // ✅ SEO FIELDS
  // ======================
  const metafields = [];

  if (updateList.includes(CONFIG.SEO_TITLE_FIELD) && hasValue(product.seo_title)) {
    metafields.push({
      namespace: "global",
      key: "title_tag",
      type: "single_line_text_field",
      value: product.seo_title
    });
  }

  if (updateList.includes(CONFIG.SEO_DESC_FIELD) && hasValue(product.seo_description)) {
    metafields.push({
      namespace: "global",
      key: "description_tag",
      type: "multi_line_text_field",
      value: product.seo_description
    });
  }

  if (metafields.length > 0) {
    payload.metafields = metafields;
  }

  return payload;
};

// ============================================
// MAIN
// ============================================

const product = items?.[0]?.json?.product;
if (!product) return [];

const updateFields = parseUpdateFields(product.updating_fields);
const updatePayload = buildUpdatePayload(product, updateFields);
updatePayload.updating_fields = product.updating_fields;

return [{ json: { product: updatePayload } }];

// Runs once per input item -- multiple metafield updates can be in flight at once.
return $input.all().map(item => {
  const res = item.json;
  if (res?.errors?.length) {
    throw new Error('Shopify GraphQL error (metafieldsSet/update): ' + JSON.stringify(res.errors));
  }
  const userErrors = res?.data?.metafieldsSet?.userErrors;
  if (userErrors?.length) {
    throw new Error('Shopify metafieldsSet (update) userErrors: ' + JSON.stringify(userErrors));
  }
  return { json: {} };
});

// Reshapes the GraphQL productSet response back into the REST-shaped
// { product: { id, title, handle, variants: [{id}] } } object that
// "📦 Parse Create Response" and "🔗 Build Collection Mappings" already expect,
// so those nodes did not need to change at all.
const res = $json;
if (res?.errors?.length) {
  throw new Error('Shopify GraphQL error (productSet): ' + JSON.stringify(res.errors));
}
const result = res?.data?.productSet;

// A HANDLE_NOT_UNIQUE error here almost always means this exact product was
// already created successfully on a prior run, but that run failed somewhere
// between the create call and the sheet write-back (so the row still looks
// "never created" and retries productSet with the same deterministic handle
// every time, colliding with itself forever). Recover instead of failing
// permanently: look up the existing product by the handle Shopify just told
// us is taken, and reconcile the sheet with it.
const handleCollision = result?.userErrors?.some(e => e.code === 'HANDLE_NOT_UNIQUE');
if (handleCollision) {
  const attemptedHandle = $('🔀 Build GraphQL: Create Product').item.json.body.variables.input.handle;
  return [{ json: { handle_collision: true, attempted_handle: attemptedHandle } }];
}

if (result?.userErrors?.length) {
  throw new Error('Shopify productSet userErrors: ' + JSON.stringify(result.userErrors));
}

const product = result?.product;
if (!product) {
  throw new Error('Shopify productSet returned no product: ' + JSON.stringify(res));
}

const variantEdge = product.variants?.edges?.[0]?.node;

return [{
  json: {
    handle_collision: false,
    product: {
      id: product.legacyResourceId,
      title: product.title,
      handle: product.handle,
      variants: [{ id: variantEdge?.legacyResourceId ?? '' }]
    }
  }
}];

const productId = $json.product.id;
const QUERY = `query GetProductCollections($id: ID!) {
  product(id: $id) {
    collections(first: 250) {
      edges { node { id legacyResourceId title } }
    }
  }
}`;
return [{ json: { body: { query: QUERY, variables: { id: `gid://shopify/Product/${productId}` } } } }];

// ===== Get previous node data =====
const nodeData = $('📝 Format Update Request').item?.json || {};

// ===== Get product_id safely =====
const product_id = $input.first()?.json?.collects?.[0]?.product_id ?? null;

// ===== Source collection IDs (1,2,3) =====
const sourceCollectionIds = [
  nodeData?.product?.collection_id1,
  nodeData?.product?.collection_id2,
  nodeData?.product?.collection_id3,
  nodeData?.product?.collection_id4,
]
  .filter(v => v !== undefined && v !== null && String(v).trim() !== '')
  .map(String);

// ===== Input collects =====
const collects = $input.first()?.json?.collects || [];
const collectCollectionIds = collects
  .map(c => c?.collection_id)
  .filter(v => v !== undefined && v !== null)
  .map(String);

// ===== 1️⃣ DELETE =====
// Exists in collects but NOT in sourceCollectionIds
const collection_id_for_delete = collects
  .filter(c => c && !sourceCollectionIds.includes(String(c.collection_id)))
  .map(c => ({
    collect_id: String(c.id),
    product_id: product_id
  }));

// ===== 2️⃣ UPDATE =====
// Exists in sourceCollectionIds but NOT in collects
const collection_id_to_update = sourceCollectionIds
  .filter(id => !collectCollectionIds.includes(id))
  .map(id => ({
    collect_id: id,
    product_id: product_id
  }));

// ===== Build FINAL OUTPUT =====
const output = [];

// ---- DELETE FORMAT ----
if (collection_id_for_delete.length > 0) {
  for (const c of collection_id_for_delete) {
    output.push({
      json: {
        collect_id: c.collect_id
      }
    });
  }
}

// ---- UPDATE FORMAT ----
if (collection_id_to_update.length > 0) {
  for (const c of collection_id_to_update) {
    output.push({
      json: {
        collect: {
          product_id: c.product_id,
          collection_id: c.collect_id
        }
      }
    });
  }
}

return output;

// Note: unlike REST's synchronous DELETE, collectionRemoveProducts is
// asynchronous (returns a background job). Nothing downstream in this
// workflow depends on immediate removal, so we only check for userErrors.
// Runs once per input item -- multiple removals can be in flight at once.
return $input.all().map(item => {
  const res = item.json;
  if (res?.errors?.length) {
    throw new Error('Shopify GraphQL error (collectionRemoveProducts): ' + JSON.stringify(res.errors));
  }
  const userErrors = res?.data?.collectionRemoveProducts?.userErrors;
  if (userErrors?.length) {
    throw new Error('Shopify collectionRemoveProducts userErrors: ' + JSON.stringify(userErrors));
  }
  return { json: {} };
});

// Pre-flight: verify every image URL still exists on the CDN before it is sent
// to Shopify. A dead link otherwise becomes a permanent "Media processing failed"
// placeholder on the product (the create/update itself still succeeds, so nothing
// downstream ever notices).
const item = $input.first().json;
const product = item.product || {};
const op = item.operation;
const images = Array.isArray(product.images) ? product.images : [];

// Updates only touch images when an IMAGE URL column is listed in Fields_to_update
const imageFieldChanged = /(^|,)\s*IMAGE URL\d+\s*(,|$)/.test(String(product.updating_fields || ''));
const relevant = op === 'create' || (op === 'update' && imageFieldChanged);

if (!relevant || images.length === 0) {
  return [{ json: { _skipCheck: true }, pairedItem: { item: 0 } }];
}
return images.map((img, idx) => ({ json: { url: img.src, alt: img.alt, idx }, pairedItem: { item: 0 } }));

const GID = (type, id) => `gid://shopify/${type}/${id}`;
const QUERY = `mutation CollectionAddProducts($id: ID!, $productIds: [ID!]!) {
  collectionAddProducts(id: $id, productIds: $productIds) {
    collection { id }
    userErrors { field message }
  }
}`;

// Runs once per input item -- "🔧 Extract Collects to update or delete" and
// "🔗 Build Collection Mappings" can both emit multiple items at once (e.g.
// several collections to add), and this node must build one request per item,
// not just the first (the default "run once for all items" Code node mode
// only sees $json as the first item, silently dropping the rest).
return $input.all().map(item => {
  const collect = item.json.collect;

  // "🔧 Extract Collects to update or delete"'s add branch depends on
  // product_id coming through the collections-fetch response -- fall back to
  // the same source "🔀 Build GraphQL: Remove from Collection" already uses,
  // and fail loudly rather than silently sending an invalid gid to Shopify.
  const productId = collect.product_id ?? $('📝 Format Update Request').item.json.product.id;
  if (!productId) {
    throw new Error('Add to Collection: could not resolve a product_id. collect=' + JSON.stringify(collect));
  }

  return {
    json: {
      body: {
        query: QUERY,
        variables: {
          id: GID('Collection', collect.collection_id),
          productIds: [GID('Product', productId)]
        }
      }
    }
  };
});

const sheet = $('🔀 Route: Create or Update').item.json.product.sheet_name;
const row_number = $('🔀 Route: Create or Update').item.json.product.row_number;
// The exact Fields_to_update value THIS update was built from -- not what's on
// the sheet right now. A parallel branch (e.g. the CAD-Image11 sync) can add a
// NEW token to this same row's Fields_to_update while this update was in flight;
// blindly writing '' here would silently erase that new token before it's ever
// acted on. Only the fields actually processed in THIS update are removed --
// see 🔀 Compute Field Diff, which re-reads the live sheet and subtracts just
// these, preserving anything added concurrently.
const processedFields = $('🔀 Route: Create or Update').item.json.product.updating_fields || '';

return [
  {
    json: {
      "sheet_name":sheet,
      "row_number":row_number,
      "Ready_to_post": "no",
      "processedFields": processedFields,
      "last_update_time": $now,
    },
  },
];

const productId = $json.product.id;
// first: 250 (not the original 50) -- a product this pipeline manages should
// never legitimately exceed 11 media items (IMAGE URL1-11), but a product
// that already accumulated duplicate media (see the existingBySlot fix in
// "\ud83d\udd00 Build GraphQL: Sync Product Images") could easily have passed 50.
// Silently truncating to the first 50 would hide the very duplicates this
// fix exists to clean up, letting the problem recur indefinitely.
const QUERY = `query GetProductMedia($id: ID!) {
  product(id: $id) {
    media(first: 250) {
      nodes {
        id
        alt
        ... on MediaImage { image { url } }
      }
    }
  }
}`;
return [{ json: { body: { query: QUERY, variables: { id: `gid://shopify/Product/${productId}` } } } }];

// ============================================
// CONFIGURATION
// ============================================
const CONFIG = {
  ADMIN_BASE_URL: 'https://admin.shopify.com/store/marblebee/products/',
  PRODUCT_BASE_URL: 'https://marblebee.myshopify.com/products/'
};

// ============================================
// EXTRACT DATA
// ============================================
const routeData = $('🔀 Route: Create or Update').first()?.json?.product ?? {};
const product = items[0]?.json?.product ?? {};
const variant = product.variants?.[0] ?? {};

// ============================================
// BUILD URLS
// ============================================
const shopifyProductUrl = product.public_shopify_url || 
  `${CONFIG.PRODUCT_BASE_URL}${product.handle ?? ''}?variant=${variant.id ?? ''}`;

const shopifyUpdateUrl = product.admin_shopify_url || 
  `${CONFIG.ADMIN_BASE_URL}${product.id ?? ''}`;

// ============================================
// BUILD OUTPUT
// ============================================
return [{
  json: {
    sheet_name: routeData.sheet_name ?? '',
    row_number: routeData.row_number ?? '',
    'Title_Shopify': (product.title ?? '').trim(),
    'Shopify_Product_URL': shopifyProductUrl,
    'Shopify_Update_product_URL': shopifyUpdateUrl,
    'Ready_to_post': 'no',
    'Fields_to_update': '',
    'create_time': $now
  }
}];

// Keeps the product gallery in step with the sheet's IMAGE URL columns.
//
// One file per image: the sheet's IMAGE URL is the file that already exists in
// Shopify Files (image-sync's upload, or the shared CAD drawing), and that SAME
// file is attached to the product (fileUpdate referencesToAdd). No copy is
// made, so the sheet URL and the product URL are identical, and a CAD file used
// by several products is one shared file. New products already work this way
// (productSet reuses the file); this step makes updates match.
//
// Only runs for products whose Fields_to_update contains an IMAGE URL token --
// nothing here touches a product nobody flagged.
//
// Matching: the exact file a sheet URL points to wins (so a product already
// showing the right file is left alone, whatever its alt says); otherwise the
// "- Image N" alt suffix (slot = sheet column) identifies the gallery item that
// is being replaced.
//
// Safety rules (each closes a failure seen on LSBLD723-725):
//  * A file the product does not own is never overwritten, re-labelled or
//    deleted -- only detached. Owned = name starts with the product number, or
//    it is a Shopify-made "_<uuid>" copy of an earlier sync.
//  * The CAD drawing is shared across products, so its alt text is never
//    touched (alt belongs to the file, not the product).
//  * No copies are ever created here. A file that cannot be found stops the
//    sync with an error naming the slot; a file that is still processing is
//    skipped until the next run.
//  * Gallery order is restored to sheet order after any change.
const SLOT_SUFFIX = / - Image (\d+)$/;
const slotOf = (alt) => {
  const m = SLOT_SUFFIX.exec(alt || '');
  return m ? Number(m[1]) : null;
};
const baseUrl = (u) => String(u || '').split('?')[0];
const SHOP_FILES = /(\/s\/files\/1\/0503\/5730\/5497\/files\/|\/cdn\/shop\/files\/)/;
const fileNameOf = (u) => {
  const last = baseUrl(u).split('/').pop() || '';
  try { return decodeURIComponent(last); } catch (e) { return last; }
};
// Identity of a file: its name when it is one of this shop's files (names are
// unique per shop); the `?v=` cache-buster and the host never matter.
const keyOf = (u) => { const b = baseUrl(u); return b ? (SHOP_FILES.test(b) ? 'f:' + fileNameOf(b) : b) : ''; };
const UUID_COPY = /_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.[A-Za-z0-9]+$/;

const mediaRes = $('📥 Get Product Media (GraphQL) (Update)').item.json;
if (mediaRes?.errors?.length) {
  throw new Error('Shopify GraphQL error (get product media): ' + JSON.stringify(mediaRes.errors));
}
const existingNodes = (mediaRes?.data?.product?.media?.nodes || []).map(n => ({
  id: n.id, alt: n.alt || '', url: n.image?.url || ''
}));

// Candidate files from the lookup node; matched by exact file name below.
const findRes = $json || {};
const lookupFailed = !!(findRes.errors && findRes.errors.length);
const candidates = new Map();
if (!lookupFailed) {
  for (const conn of Object.values(findRes.data || {})) {
    for (const n of (conn?.nodes || [])) {
      const k = keyOf(n?.image?.url);
      if (k && !candidates.has(k)) candidates.set(k, n);
    }
  }
}

const upd = $('📝 Format Update Request').item.json.product;
const productId = upd.id;
const productGid = `gid://shopify/Product/${productId}`;
const route = $('🔀 Route: Create or Update').item.json.product || {};
const productNumber = String(route.product_number || '').trim();
const cadKey = keyOf(route.cad_drawing_url);

const desired = [];
for (const img of (upd.images || [])) {
  const slot = slotOf(img.alt);
  if (slot === null || !img.src) continue;
  desired.push({ slot, src: img.src, alt: img.alt || '', key: keyOf(img.src) });
}
desired.sort((a, b) => a.slot - b.slot);
const desiredKeys = new Set(desired.map(d => d.key));
const isCad = (d) => d.slot === 11 || (!!cadKey && d.key === cadKey);

const prefixed = (u) => {
  const f = fileNameOf(u);
  return !!productNumber && (f.startsWith(productNumber + '-') || f.startsWith(productNumber + '_') || f.startsWith(productNumber + '.'));
};
const isOwned = (u) => UUID_COPY.test(fileNameOf(u)) || prefixed(u);

const existingBySlot = new Map();
const existingByKey = new Map();
for (const n of existingNodes) {
  const s = slotOf(n.alt);
  if (s !== null) {
    const b = existingBySlot.get(s) || [];
    b.push(n);
    existingBySlot.set(s, b);
  }
  if (n.url) existingByKey.set(keyOf(n.url), n);
}

const attach = [];      // { id, alt (optional), add }
const detachIds = [];
const deleteIds = [];
const claimed = new Set();
const finalIdBySlot = new Map();
const missing = [];
let changedGallery = false;

for (const d of desired) {
  // 1. This exact file is already on the product -> keep it, even if its alt
  //    names another slot: the sheet URL is the source of truth. Alt is only
  //    corrected on files this product owns (never on the shared CAD).
  const present = existingByKey.get(d.key);
  if (present) {
    claimed.add(present.id);
    finalIdBySlot.set(d.slot, present.id);
    if (present.alt !== d.alt && isOwned(present.url) && !isCad(d)) {
      attach.push({ id: present.id, alt: d.alt, add: false });
      // Precaution: any change to the gallery gets the order checked and restored afterwards (see the
      // gallery order stage). Not proven to be needed for alt-only changes; harmless if the order is already right.
      changedGallery = true;
    }
    continue;
  }

  // 2. Attach the file the sheet URL points to.
  const f = candidates.get(d.key);
  if (!f) {
    missing.push(`Image ${d.slot} (${fileNameOf(d.src) || d.src})`);
    continue;
  }
  if (f.fileStatus !== 'READY') {
    // Still processing: keep whatever is in that slot now and retry next run.
    for (const c of (existingBySlot.get(d.slot) || [])) {
      if (claimed.has(c.id)) continue;
      claimed.add(c.id);
      if (!finalIdBySlot.has(d.slot)) finalIdBySlot.set(d.slot, c.id);
    }
    continue;
  }
  const entry = { id: f.id, add: true };
  if (!isCad(d)) entry.alt = d.alt;      // CAD is shared: its alt stays as it is
  attach.push(entry);
  claimed.add(f.id);
  finalIdBySlot.set(d.slot, f.id);
  changedGallery = true;
}

if (missing.length > 0) {
  throw new Error(
    `Image sync stopped for ${productNumber || productId}: ${missing.length} sheet image(s) not found in Shopify Files -- ` +
    missing.join(', ') +
    (lookupFailed ? ` (file lookup returned an error: ${JSON.stringify(findRes.errors).slice(0, 300)})` : '') +
    '. Nothing was changed. Fix the IMAGE URL cell (or re-run image-sync) and flag the row again.'
  );
}

// Everything on the product that no sheet slot claimed: replaced copies or
// files, removed slots, duplicates. Own files are deleted; anything not provably
// ours is only detached from the product.
for (const n of existingNodes) {
  if (claimed.has(n.id)) continue;
  const slot = slotOf(n.alt);
  if (slot !== null) {
    const stillWanted = n.url && desiredKeys.has(keyOf(n.url));
    if (isOwned(n.url) && !stillWanted) deleteIds.push(n.id); else detachIds.push(n.id);
    changedGallery = true;
  } else if (prefixed(n.url)) {
    // Alt-less upload made by this pipeline before alt tagging existed.
    deleteIds.push(n.id);
    changedGallery = true;
  }
}

const FILE_UPDATE = `mutation FileUpdate($files: [FileUpdateInput!]!) {
  fileUpdate(files: $files) {
    files { id }
    userErrors { field message code }
  }
}`;
const operations = [];

if (attach.length > 0) {
  operations.push({
    type: 'attach',
    body: {
      query: FILE_UPDATE,
      variables: {
        files: attach.map(a => {
          const o = { id: a.id };
          if (a.alt !== undefined) o.alt = a.alt;
          if (a.add) o.referencesToAdd = [productGid];
          return o;
        })
      }
    }
  });
}
if (detachIds.length > 0) {
  operations.push({
    type: 'detach',
    body: {
      query: FILE_UPDATE,
      variables: { files: detachIds.map(id => ({ id, referencesToRemove: [productGid] })) }
    }
  });
}
if (deleteIds.length > 0) {
  operations.push({
    type: 'delete',
    body: {
      query: `mutation FileDelete($fileIds: [ID!]!) {
  fileDelete(fileIds: $fileIds) {
    deletedFileIds
    userErrors { field message }
  }
}`,
      variables: { fileIds: deleteIds }
    }
  });
}

// The gallery order is restored in a SEPARATE, later stage (see "🧩 Collect Sync Results" onward).
// It used to be sent right here, back to back with the attach / delete above. Shopify applies file
// attach and delete asynchronously, so the reorder arrived before the files were on the product and
// was silently dropped (a failed reorder was ignored by design), leaving photos in whatever order
// they landed -- the featured photo changed on ~200 fireplaces. Now: wait, confirm the files are on
// the product, reorder, re-read, verify.
const desiredIds = desired.map(d => finalIdBySlot.get(d.slot)).filter(Boolean);
const curIds = existingNodes.map(n => n.id).filter(id => desiredIds.includes(id));
const orderMismatch = desiredIds.length > 1 && curIds.length === desiredIds.length && JSON.stringify(curIds) !== JSON.stringify(desiredIds);
const plan = { productGid, desiredIds, wantReorder: changedGallery || orderMismatch || attach.length > 0 };

if (operations.length === 0) {
  return [{ json: { message: 'No image changes to sync', plan } }];
}

return operations.map(op => ({ json: { ...op, plan } }));

// Reads the SAME payload object built (unchanged) by "📝 Format Update Request".
// Only translates it into GraphQL productUpdate / productVariantsBulkUpdate calls.
const p = $json.product;
const numericId = p.id;

const productInput = { id: `gid://shopify/Product/${numericId}` };
if (p.body_html !== undefined) productInput.descriptionHtml = p.body_html;
if (p.title !== undefined) productInput.title = p.title;
if (p.tags !== undefined) {
  productInput.tags = String(p.tags).split(',').map(t => t.trim()).filter(Boolean);
}
if (Array.isArray(p.metafields) && p.metafields.length > 0) {
  productInput.metafields = p.metafields;
}

// Image sync is handled separately (see "✅ Check if Image Update Needed" and
// its branch) via fileUpdate/productCreateMedia -- productUpdate's own `media`
// argument only ever ADDS new media, it can never replace an existing image in
// place, so resubmitting the full image list here on every image-triggered
// update was silently duplicating every unchanged image alongside the one that
// actually changed.
const PRODUCT_UPDATE_QUERY = `mutation ProductUpdate($product: ProductUpdateInput!) {
  productUpdate(product: $product) {
    product { id }
    userErrors { field message }
  }
}`;

const variables = { product: productInput };

// productUpdate does not support variant fields (Shopify docs) -- price/weight
// need a separate productVariantsBulkUpdate call, same as REST effectively
// needed a variant sub-object but in one call; here it's two calls.
const variant = (Array.isArray(p.variants) && p.variants[0]) || null;
const needsVariantUpdate = !!(variant && variant.id && (variant.price !== undefined || variant.weight !== undefined));

let variantBody = null;
if (needsVariantUpdate) {
  const variantInput = { id: `gid://shopify/ProductVariant/${variant.id}` };
  // never push a missing / 0 price onto an existing product
if (variant.price !== undefined && Number(variant.price) > 0) variantInput.price = variant.price;
  if (variant.weight !== undefined) {
    // Marblebee's weight unit is always 'kg' (CONFIG.WEIGHT_UNIT in the sibling
    // create-path node) -- there is no per-item weight_unit on the update payload.
    variantInput.inventoryItem = {
      measurement: { weight: { value: variant.weight, unit: 'KILOGRAMS' } }
    };
  }

  const PRODUCT_VARIANTS_BULK_UPDATE_QUERY = `mutation ProductVariantsBulkUpdate($productId: ID!, $variants: [ProductVariantsBulkInput!]!) {
  productVariantsBulkUpdate(productId: $productId, variants: $variants) {
    productVariants { id }
    userErrors { field message }
  }
}`;

  variantBody = {
    query: PRODUCT_VARIANTS_BULK_UPDATE_QUERY,
    variables: { productId: `gid://shopify/Product/${numericId}`, variants: [variantInput] }
  };
}

return [{
  json: {
    body: { query: PRODUCT_UPDATE_QUERY, variables },
    needsVariantUpdate,
    variantBody
  }
}];

// metafieldsDelete addresses metafields by ownerId + namespace + key (the
// singular metafieldDelete-by-id mutation no longer exists on current API
// versions) -- owner_id/namespace/key were added onto this "delete" operation
// object in "🧠 Sync Metafields" (additive fields only).
const QUERY = `mutation MetafieldsDelete($metafields: [MetafieldIdentifierInput!]!) {
  metafieldsDelete(metafields: $metafields) {
    deletedMetafields { key }
    userErrors { field message }
  }
}`;

// Runs once per input item -- multiple metafield deletes can be in flight at
// once (the default "run once for all items" Code node mode only sees $json
// as the first item, silently dropping the rest).
return $input.all().map(item => {
  const op = item.json;
  return {
    json: {
      body: {
        query: QUERY,
        variables: {
          metafields: [{
            ownerId: `gid://shopify/Product/${op.owner_id}`,
            namespace: op.namespace,
            key: op.key
          }]
        }
      }
    }
  };
});

const QUERY = `query GetOnlineStorePublication {
  publications(first: 10) {
    nodes { id name }
  }
}`;
return [{ json: { body: { query: QUERY } } }];

const QUERY = `mutation MetafieldsSet($metafields: [MetafieldsSetInput!]!) {
  metafieldsSet(metafields: $metafields) {
    metafields { id }
    userErrors { field message code }
  }
}`;

// Runs once per input item -- "🧠 Sync Metafields" can emit multiple create
// operations at once (e.g. Material Catalog URL + Care Guide URL both new in
// the same run), and this node must build one request per item, not just the
// first (the default "run once for all items" Code node mode only sees $json
// as the first item, silently dropping the rest).
return $input.all().map(item => {
  const m = item.json.payload.metafield;
  return {
    json: {
      body: {
        query: QUERY,
        variables: {
          metafields: [{
            ownerId: `gid://shopify/Product/${m.owner_id}`,
            namespace: m.namespace,
            key: m.key,
            type: m.type,
            value: m.value
          }]
        }
      }
    }
  };
});

// Reshapes into the REST-shaped { metafields: [{id, namespace, key, value, type}] }
// array that "🧠 Sync Metafields (CREATE / UPDATE / DELETE)" already expects unchanged.
const res = $json;
if (res?.errors?.length) {
  throw new Error('Shopify GraphQL error (get metafields): ' + JSON.stringify(res.errors));
}
const edges = res?.data?.product?.metafields?.edges || [];
const metafields = edges.map(e => ({
  id: e.node.id,
  namespace: e.node.namespace,
  key: e.node.key,
  value: e.node.value,
  type: e.node.type
}));
return [{ json: { metafields } }];

const productId = $json.product.id;
const QUERY = `query GetProductMetafields($id: ID!) {
  product(id: $id) {
    metafields(first: 250) {
      edges { node { id legacyResourceId namespace key value type } }
    }
  }
}`;
return [{ json: { body: { query: QUERY, variables: { id: `gid://shopify/Product/${productId}` } } } }];

// Runs once per input item -- multiple metafield creates can be in flight at once.
return $input.all().map(item => {
  const res = item.json;
  if (res?.errors?.length) {
    throw new Error('Shopify GraphQL error (metafieldsSet/create): ' + JSON.stringify(res.errors));
  }
  const userErrors = res?.data?.metafieldsSet?.userErrors;
  if (userErrors?.length) {
    throw new Error('Shopify metafieldsSet (create) userErrors: ' + JSON.stringify(userErrors));
  }
  return { json: {} };
});

const res = $json;
const errors = res?.errors;
const userErrors = res?.data?.publishablePublish?.userErrors;

// Reordering this node ahead of "🔗 Build Collection Mappings" and
// "📦 Parse Create Response" means it is now their direct input -- both expect
// a `.product` field (the shape "🔀 Adapt Response: Create Product" produces),
// so it must be carried forward here or those nodes silently break (one throws
// on undefined.id, the other silently falls back to {} and writes blank data
// to the sheet).
const product = $('🔀 Adapt Response: Create Product').item.json.product;

// A failed publish must not throw and halt the run -- the sheet write-back
// (which records the product's Shopify URL) needs to happen regardless, or the
// row looks "not yet created" next run and retries productSet with the same
// handle, guaranteed to fail with HANDLE_NOT_UNIQUE since the product already
// exists. A product left unpublished here is caught by the periodic
// "unpublished product" reconciliation check instead.
if (errors?.length || userErrors?.length) {
  return [{ json: { product, published: false, publish_error: JSON.stringify(errors?.length ? errors : userErrors) } }];
}
return [{ json: { product, published: true } }];

// Reads the SAME cleanedProduct object built (unchanged) by "📝 Format Create Request".
const p = $json.product;

const tagsArr = String(p.tags || '').split(',').map(t => t.trim()).filter(Boolean);
const WEIGHT_UNIT_MAP = { kg: 'KILOGRAMS', g: 'GRAMS', lb: 'POUNDS', oz: 'OUNCES' };
const variant = (Array.isArray(p.variants) && p.variants[0]) || {};

// Second guard (the main pipeline already skips rows without a price): never create a product
// whose price is missing or 0 -- it would be orderable for free.
if (!(Number(variant.price) > 0)) {
  throw new Error(`Refusing to create "${p.title}" (${p.handle}): price is missing or 0`);
}

// Shopify requires an explicit productOptions entry whenever `variants` is
// present on productSet, even for a plain single-SKU product with no real
// customer-facing options -- omitting it (or passing optionValues: []) fails
// with PRODUCT_OPTIONS_INPUT_MISSING. "Title" / "Default Title" is Shopify's
// own magic-string convention for its internal single-default-variant option
// (exact casing required, confirmed against a live productSet call) -- it's
// the same hidden pseudo-option a plain REST product without options gets,
// so it never shows a variant selector on the storefront.
const DEFAULT_OPTION_NAME = 'Title';
const DEFAULT_OPTION_VALUE = 'Default Title';

const variantInput = {
  optionValues: [
    { optionName: DEFAULT_OPTION_NAME, name: DEFAULT_OPTION_VALUE }
  ],
  price: variant.price,
  inventoryItem: {
    requiresShipping: !!variant.requires_shipping,
    measurement: {
      weight: {
        value: variant.weight,
        unit: WEIGHT_UNIT_MAP[variant.weight_unit] || 'KILOGRAMS'
      }
    }
  }
};

const input = {
  title: p.title,
  vendor: p.vendor,
  productType: p.product_type,
  tags: tagsArr,
  handle: p.handle,
  descriptionHtml: p.body_html || '',
  // GraphQL's ACTIVE status only means "publishable", unlike REST where a
  // created product is also auto-published to the Online Store channel --
  // see the separate publish step appended after this create call.
  status: 'ACTIVE',
  productOptions: [
    { name: DEFAULT_OPTION_NAME, values: [{ name: DEFAULT_OPTION_VALUE }] }
  ],
  variants: [variantInput]
};

if (Array.isArray(p.metafields) && p.metafields.length > 0) {
  input.metafields = p.metafields;
}

if (Array.isArray(p.images) && p.images.length > 0) {
  input.files = p.images.map(img => ({
    originalSource: img.src,
    alt: img.alt || '',
    contentType: 'IMAGE'
  }));
}

const PRODUCT_SET_QUERY = `mutation ProductSet($input: ProductSetInput!, $synchronous: Boolean!) {
  productSet(input: $input, synchronous: $synchronous) {
    product {
      id
      legacyResourceId
      title
      handle
      variants(first: 1) {
        edges { node { id legacyResourceId } }
      }
    }
    userErrors { field message code }
  }
}`;

return [{
  json: {
    body: { query: PRODUCT_SET_QUERY, variables: { input, synchronous: true } }
  }
}];

const GID = (type, id) => `gid://shopify/${type}/${id}`;
const QUERY = `mutation CollectionRemoveProducts($id: ID!, $productIds: [ID!]!) {
  collectionRemoveProducts(id: $id, productIds: $productIds) {
    job { id done }
    userErrors { field message }
  }
}`;

// Runs once per input item -- "🔧 Extract Collects to update or delete" can
// emit multiple collections to remove at once (the default "run once for all
// items" Code node mode only sees $json as the first item, silently dropping
// the rest).
return $input.all().map(item => {
  // "🔧 Extract Collects to update or delete" only carries collect_id forward
  // on its delete branch (REST never needed product_id for a DELETE-by-collect-id
  // call) -- GraphQL's collectionRemoveProducts needs both, so product_id is
  // pulled back in here from the same source node the rest of this branch
  // already reads from, without touching that existing decision-logic node.
  const collectionId = item.json.collect_id;
  const productId = $('📝 Format Update Request').item.json.product.id;

  return {
    json: {
      body: {
        query: QUERY,
        variables: { id: GID('Collection', collectionId), productIds: [GID('Product', productId)] }
      }
    }
  };
});

const input = $input.first().json;

// Always safe unwrap (n8n sometimes wraps arrays)
const metafields = input.metafields || [];

// IMPORTANT: only take fields that actually exist in update node
const productWrapper = $('📝 Format Update Request').item.json;
const product = productWrapper.product || {};

// Metafield type per field key -- not all custom fields are URLs
const FIELD_TYPES = {
  material_catalog_url: 'url',
  care_guide_url: 'url',
  cad_drawing_url: 'url',
  price_unit_suffix: 'single_line_text_field'
};

// Only include fields that are actually present (not undefined)
const sheetData = {};

if (product.hasOwnProperty('material_catalog_url')) {
  sheetData.material_catalog_url = product.material_catalog_url;
}

if (product.hasOwnProperty('care_guide_url')) {
  sheetData.care_guide_url = product.care_guide_url;
}

if (product.hasOwnProperty('cad_drawing_url')) {
  sheetData.cad_drawing_url = product.cad_drawing_url;
}

if (product.hasOwnProperty('price_unit_suffix')) {
  sheetData.price_unit_suffix = product.price_unit_suffix;
}

const operations = [];

// Only iterate actual incoming fields
for (const [key, newValueRaw] of Object.entries(sheetData)) {

  const newValue = (newValueRaw || '').toString().trim();
  const fieldType = FIELD_TYPES[key] || 'url';

  const existingField = metafields.find(
    m => m.namespace === "custom" && m.key === key
  );

  // =========================
  // DELETE (ONLY if explicitly empty string)
  // =========================
  if (newValue === '' && existingField) {
    operations.push({
      type: "delete",
      id: existingField.id,
      // Added for the GraphQL metafieldsDelete call, which addresses metafields
      // by owner+namespace+key rather than by the metafield's own id.
      owner_id: product.id,
      namespace: "custom",
      key
    });
    continue;
  }

  // =========================
  // CREATE
  // =========================
  if (newValue !== '' && !existingField) {
    operations.push({
      type: "create",
      payload: {
        metafield: {
          namespace: "custom",
          key,
          type: fieldType,
          value: newValue,
          owner_id: product.id,
          owner_resource: "product"
        }
      }
    });
    continue;
  }

  // =========================
  // UPDATE
  // =========================
  if (
    newValue !== '' &&
    existingField &&
    existingField.value !== newValue
  ) {
    operations.push({
      type: "update",
      id: existingField.id,
      // Added for the GraphQL metafieldsSet call, which upserts by
      // owner+namespace+key rather than needing the metafield's own id.
      owner_id: product.id,
      namespace: "custom",
      key,
      payload: {
        metafield: {
          id: existingField.id,
          value: newValue,
          type: fieldType
        }
      }
    });
  }
}

// =========================
// SAFE OUTPUT
// =========================
if (operations.length === 0) {
  return [{ json: { message: "No metafield changes detected" } }];
}

return operations.map(op => ({ json: op }));

const QUERY = `query FindProductByHandle($handle: String!) {
  productByHandle(handle: $handle) {
    id
    legacyResourceId
    title
    handle
    variants(first: 1) {
      edges { node { id legacyResourceId } }
    }
  }
}`;
return [{ json: { body: { query: QUERY, variables: { handle: $json.attempted_handle } } } }];

const res = $json;
if (res?.errors?.length) {
  throw new Error('Shopify GraphQL error (productUpdate): ' + JSON.stringify(res.errors));
}
const userErrors = res?.data?.productUpdate?.userErrors;
if (userErrors?.length) {
  throw new Error('Shopify productUpdate userErrors: ' + JSON.stringify(userErrors));
}

const build = $('🔀 Build GraphQL: Update Product').item.json;
return [{ json: { needsVariantUpdate: build.needsVariantUpdate, variantBody: build.variantBody } }];

// Looks up the Shopify File object behind each sheet IMAGE URL (photos and the
// CAD drawing alike) so the next node can ATTACH that original file to the
// product -- one file, same URL in the sheet and on the product -- instead of
// letting productCreateMedia make a second, differently-named copy of it. Files
// are matched by exact file name in the next node; this node only fetches
// candidates.
const baseUrl = (u) => String(u || '').split('?')[0];
const SHOP_FILES = /(\/s\/files\/1\/0503\/5730\/5497\/files\/|\/cdn\/shop\/files\/)/;
const fileNameOf = (u) => {
  const last = baseUrl(u).split('/').pop() || '';
  try { return decodeURIComponent(last); } catch (e) { return last; }
};
const keyOf = (u) => { const b = baseUrl(u); return b ? (SHOP_FILES.test(b) ? 'f:' + fileNameOf(b) : b) : ''; };
const SLOT_SUFFIX = / - Image (\d+)$/;
const slotOf = (alt) => { const m = SLOT_SUFFIX.exec(alt || ''); return m ? Number(m[1]) : null; };

const mediaRes = $json;
const attachedKeys = new Set(
  (mediaRes?.data?.product?.media?.nodes || []).map(n => keyOf(n?.image?.url)).filter(Boolean)
);

const desiredImages = $('📝 Format Update Request').item.json.product.images || [];
const route = $('🔀 Route: Create or Update').item.json.product || {};
const productNumber = String(route.product_number || '').trim();

const SAFE_PREFIX = /^[A-Za-z0-9._-]+/;
const wanted = [];                 // [alias, filename prefix]
let needProductPrefix = false;
for (const img of desiredImages) {
  const slot = slotOf(img.alt);
  if (slot === null || !img.src) continue;
  const key = keyOf(img.src);
  if (attachedKeys.has(key)) continue;                 // already on the product
  if (!key.startsWith('f:')) continue;                 // not one of this shop's files
  const name = fileNameOf(img.src);
  if (productNumber && name.startsWith(productNumber)) needProductPrefix = true;
  else { const m = SAFE_PREFIX.exec(name); if (m) wanted.push(['f' + slot, m[0]]); }
}

const FIELDS = '{ nodes { id fileStatus ... on MediaImage { image { url } } } }';
const parts = [];
if (needProductPrefix) {
  parts.push(`p: files(first: 100, query: ${JSON.stringify('filename:' + productNumber + '*')}) ${FIELDS}`);
}
const used = new Set();
for (const [alias, prefix] of wanted) {
  if (used.has(alias)) continue;
  used.add(alias);
  parts.push(`${alias}: files(first: 10, query: ${JSON.stringify('filename:' + prefix + '*')}) ${FIELDS}`);
}

const query = parts.length
  ? `query FindOriginalFiles {\n${parts.join('\n')}\n}`
  : 'query NoLookupNeeded { shop { id } }';

return [{ json: { body: { query } } }];

// Fixes a race between this update's Fields_to_update clear and any OTHER
// branch (e.g. the CAD-Image11 sync) writing a NEW token to the same row's
// Fields_to_update while this update was in flight. Re-reads the sheet fresh
// (right now, not the stale snapshot from when this row's processing started)
// and only removes the specific fields THIS update actually processed --
// anything else present now (added concurrently) is preserved untouched.
const input = $('📦 Parse Update Response').item.json;
const rows = $input.all().map(i => i.json);
const row = rows.find(r => String(r.row_number) === String(input.row_number));
const currentFresh = row ? String(row['Fields_to_update'] || '') : '';

const processed = new Set(String(input.processedFields || '').split(',').map(t => t.trim()).filter(Boolean));
const remaining = currentFresh.split(',').map(t => t.trim()).filter(Boolean).filter(t => !processed.has(t));

return [{
  json: {
    sheet_name: input.sheet_name,
    row_number: input.row_number,
    Ready_to_post: input.Ready_to_post,
    last_update_time: input.last_update_time,
    Fields_to_update: remaining.join(','),
  }
}];

// One item for the whole product, whether or not file operations ran (this node is reached from
// "Check Sync Images Result" -- after every attach / delete answered -- or directly when there was
// nothing to attach or delete). Carries the plan from "Build GraphQL: Sync Product Images".
const plan = $('🔀 Build GraphQL: Sync Product Images').first().json.plan;
const READ = `query GetProductMedia($id: ID!) {
  product(id: $id) { media(first: 250) { nodes { id alt ... on MediaImage { image { url } } } } }
}`;
return [{ json: { plan, readBody: { query: READ, variables: { id: plan.productGid } } } }];

// Compares the product's CURRENT gallery with the sheet order. Only files that are already on the
// product are moved, so a file that has not arrived yet can never make the whole reorder fail.
const plan = $('🧩 Collect Sync Results').first().json.plan;
const media = $input.first().json.data?.product?.media?.nodes || [];
const cur = media.map(m => m.id);
const present = plan.desiredIds.filter(id => cur.includes(id));
const missing = plan.desiredIds.filter(id => !cur.includes(id));
const inOrder = JSON.stringify(cur.slice(0, present.length)) === JSON.stringify(present);
const moves = (!inOrder && present.length > 1) ? present.map((id, i) => ({ id, newPosition: String(i) })) : [];
const REORDER = `mutation ProductReorderMedia($id: ID!, $moves: [MoveInput!]!) {
  productReorderMedia(id: $id, moves: $moves) {
    job { id }
    mediaUserErrors { field message code }
  }
}`;
return [{ json: {
  allFilesPresent: missing.length === 0, missing, inOrder, needsReorder: moves.length > 0,
  reorderBody: { query: REORDER, variables: { id: plan.productGid, moves } }
} }];

// Compares the product's CURRENT gallery with the sheet order. Only files that are already on the
// product are moved, so a file that has not arrived yet can never make the whole reorder fail.
const plan = $('🧩 Collect Sync Results').first().json.plan;
const media = $input.first().json.data?.product?.media?.nodes || [];
const cur = media.map(m => m.id);
const present = plan.desiredIds.filter(id => cur.includes(id));
const missing = plan.desiredIds.filter(id => !cur.includes(id));
const inOrder = JSON.stringify(cur.slice(0, present.length)) === JSON.stringify(present);
const moves = (!inOrder && present.length > 1) ? present.map((id, i) => ({ id, newPosition: String(i) })) : [];
const REORDER = `mutation ProductReorderMedia($id: ID!, $moves: [MoveInput!]!) {
  productReorderMedia(id: $id, moves: $moves) {
    job { id }
    mediaUserErrors { field message code }
  }
}`;
return [{ json: {
  allFilesPresent: missing.length === 0, missing, inOrder, needsReorder: moves.length > 0,
  reorderBody: { query: REORDER, variables: { id: plan.productGid, moves } }
} }];

// Re-reads the gallery after the reorder and checks it. A reorder is an asynchronous job, so this
// is the only way to know it worked. The result is recorded in this node's output; it does NOT fail
// the product's sync (the photos exist either way), but it is no longer silent.
const plan = $('🧩 Collect Sync Results').first().json.plan;
const media = $input.first().json.data?.product?.media?.nodes || [];
const cur = media.map(m => m.id);
const present = plan.desiredIds.filter(id => cur.includes(id));
const ok = JSON.stringify(cur.slice(0, present.length)) === JSON.stringify(present);
return [{ json: { reorderVerified: ok, wanted: present, actual: cur.slice(0, present.length), message: ok ? 'Gallery is in sheet order' : 'GALLERY ORDER NOT RESTORED -- run the Repair Gallery Order workflow for this product' } }];
